INSERT INTO `featured_products` (`id`, `image`, `heading`, `description`, `status`, `created_at`, `updated_at`) VALUES
(3, 'featured-products/1767593885_images (4).jpeg', '3D Motion Capture System', 'Vicon motion capture systems are high-precision optical tracking solutions that record and analyze detailed human movement for biomechanics, animation, sports science, and research applications.', 'active', '2025-12-30 06:40:53', '2026-01-05 06:18:05'),
(4, 'featured-products/1767593898_trigno.png', 'Wireless EMG System', 'Trigno Centro Avanti System is a wireless biomechanical and EMG acquisition system that synchronously captures high-fidelity muscle activity and movement data for research, rehabilitation, and sports performance analysis.', 'active', '2025-12-30 06:43:29', '2026-01-05 06:18:18'),
(5, 'featured-products/1767593913_images.jpeg', 'Handheld Dynamometers', 'Handheld dynamometers are compact, high-accuracy digital devices that deliver precise, repeatable muscle strength measurements for clinical, rehabilitation, and sports assessments in multiple units (N, kgf, lbs).', 'active', '2025-12-30 06:43:48', '2026-01-05 06:18:33'),
(7, 'featured-products/1767593874_Anthro.png', 'Anthropometer', 'Anthropometric equipment is used to accurately measure human body dimensions such as height, weight, limb length, and body proportions for ergonomics, healthcare, sports, and research applications.', 'active', '2026-01-01 10:33:29', '2026-01-05 06:17:54'),
(8, 'featured-products/1767593929_force torque.png', 'Force & Torque Sensor', 'Force and Torque Sensor precisely measures applied linear force and rotational torque, converting them into accurate electrical signals for testing, automation, and research applications.', 'active', '2026-01-02 14:59:57', '2026-01-05 06:18:49');

