(1, 'Trigno Centro', NULL, 'Engineering', 'products/thumbnails/1767627180_capture-engineering.png', '[\"products\\/gallery\\/1767077500_gl2.png\",\"products\\/gallery\\/1767077500_gl3.png\",\"products\\/gallery\\/1767077500_gl4.png\",\"products\\/gallery\\/1767077500_gl5.png\",\"products\\/gallery\\/1767077500_gl6.png\"]', NULL, '2025-12-30 06:49:43', '2026-01-05 15:33:00', '<p>Central hub enabling seamless synchronization, control, and data acquisition for Trigno wireless sensors.</p>', 'active', 1, 0, 0, 0, 0, 0),
(2, 'VALKYRIE', 'Engineering', 'Life Science', 'products/thumbnails/1767595263_Untitled design (8).png', '[]', NULL, '2025-12-30 12:33:13', '2026-01-05 06:41:03', '<p>A dynamic camera for a changing a world valkyrie is the new foundation of your motion capture system.</p>', 'active', 1, 1, 1, 0, 1, 1),
(6, 'Vero', NULL, 'Life Science', 'products/thumbnails/1767596375_vero.png', '[]', NULL, '2026-01-02 18:03:03', '2026-01-05 06:59:35', '<p>High-performance motion capture cameras delivering precision, speed, and flexibility across research and engineering applications.</p>', 'active', 1, 1, 1, 0, 1, 1),
(7, 'Biomechanical modeling software', 'Biomechanics, Motion capture', 'Life Science', 'products/thumbnails/1767595718_Gold and Beige Elegant Jewellery Sale Instagram Post-3.png', '[]', NULL, '2026-01-04 06:39:05', '2026-01-05 06:48:38', '<p>Biomechanical modeling software delivering intuitive musculoskeletal analysis and objective, quantitative human movement insights.</p>', 'active', 1, 1, 1, 0, 1, 1),
(8, 'Multi Axis Force/ Torque sensor', 'load cells', 'Engineering', 'products/thumbnails/1767595658_Multi Axis Load cells-3.png', '[]', NULL, '2026-01-04 08:27:18', '2026-01-05 06:47:38', '<p>Multi-axis load cells are precision sensors designed to measure forces and moments along multiple axes simultaneously</p>', 'active', 1, 1, 1, 0, 1, 1);

