INSERT INTO `product_features` (`id`, `product_id`, `type`, `page_heading`, `sub_heading`, `title`, `icon_image`, `description`, `created_at`, `updated_at`) VALUES
(2, 1, 'card1', 'Capture EMG Your Way', 'For every application, Trigno Centro Supports your research', NULL, NULL, NULL, '2025-12-30 07:02:08', '2025-12-30 07:02:08'),
(3, 1, 'card2', NULL, NULL, 'Neurophysiology', NULL, 'Neurophysiology studies how the nervous system functions, transmitting signals that control movement, behavior, and bodily processes.', '2025-12-30 07:02:08', '2025-12-30 07:02:08'),
(4, 1, 'card2', NULL, NULL, 'Movement Sciences', NULL, 'Movement Sciences studies human movement to enhance performance, prevent injuries, and promote overall physical health.', '2025-12-30 07:02:08', '2025-12-30 07:02:08'),
(5, 1, 'card2', NULL, NULL, 'Engineering', NULL, 'We Texon Corpporation offer class C3 Load cells for precesie weighing applications. our Load cell range starts from 110 gm to 300 Ton.', '2025-12-30 07:02:08', '2025-12-30 07:02:08'),
(18, 6, 'card1', 'Precision Without Complexity', 'Smarter motion capture starts here', NULL, NULL, NULL, '2026-01-02 18:55:02', '2026-01-02 18:55:02'),
(19, 6, 'card2', NULL, NULL, 'Engineering', NULL, 'High-precision motion capture for accurate engineering analysis and validation.\r\nIdeal for kinematics, robotics, and product design optimization.', '2026-01-02 18:55:02', '2026-01-02 18:55:02'),
(20, 6, 'card2', NULL, NULL, 'Life Science', NULL, 'Reliable movement data to advance biomechanics and life science research.\r\nSupports clinical studies, gait analysis, and human performance evaluation.', '2026-01-02 18:55:02', '2026-01-02 18:55:02'),
(21, 6, 'card2', NULL, NULL, 'Ergonomics', NULL, 'Quantifying human motion to improve ergonomic design and workplace safety.\r\nEnables data-driven assessment of posture, movement, and injury risk.', '2026-01-02 18:55:02', '2026-01-02 18:55:02'),
(22, 2, 'card1', 'Capture Valkyrie Your Way', 'For every application, Valkyrie Supports your research', NULL, NULL, NULL, '2026-01-02 19:08:57', '2026-01-02 19:08:57'),
(23, 2, 'card2', NULL, NULL, 'Clinical Gait Analysis', NULL, 'The Valkyrie system accurately assesses and quantifies human movement with precision. It helps track motion patterns to support rehabilitation and therapy planning. This makes it ideal for advanced medical research and clinical studies.', '2026-01-02 19:08:57', '2026-01-02 19:08:57'),
(24, 2, 'card2', NULL, NULL, 'Sports Science', NULL, 'The Valkyrie system captures precise motion data to analyze every movement. It helps optimize athlete training, improve techniques, and enhance overall performance. This makes it ideal for biomechanics research and high-performance sports analysis.', '2026-01-02 19:08:57', '2026-01-02 19:08:57'),
(25, 2, 'card2', NULL, NULL, 'Ergonomics & Workplace Design', NULL, 'Valkyrie captures detailed human motion to evaluate posture and movement. It helps identify risks and optimize workplace safety and efficiency. This makes it ideal for ergonomic studies, product design, and injury prevention research', '2026-01-02 19:08:57', '2026-01-02 19:08:57'),
(29, 7, 'card1', 'Software', NULL, NULL, NULL, NULL, '2026-01-04 07:18:38', '2026-01-04 07:18:38'),
(30, 7, 'card2', NULL, NULL, 'Automotive  Industry', NULL, 'Enables automotive engineers to analyze human movement, ergonomics, and occupant safety for optimized vehicle design.', '2026-01-04 07:18:38', '2026-01-04 07:18:38'),
(31, 7, 'card2', NULL, NULL, 'Sports Performance & Injury Prevention', NULL, 'Analyze athlete biomechanics to improve performance and reduce injury risk.', '2026-01-04 07:18:38', '2026-01-04 07:18:38'),
(32, 7, 'card2', NULL, NULL, 'Clinical Rehabilitation & Gait Analysis', NULL, 'Provides objective metrics to guide treatment plans and track patient recovery.', '2026-01-04 07:18:38', '2026-01-04 07:18:38'),
(33, 8, 'card1', 'Unlimited Possibilities', 'Measure Every Force and Torque. Every Axis.', NULL, NULL, NULL, '2026-01-04 09:56:29', '2026-01-04 09:56:29'),
(34, 8, 'card2', NULL, NULL, 'Automotive Testing', NULL, 'Measures complex loads and torques on vehicle components to validate performance, durability, and safety.', '2026-01-04 09:56:29', '2026-01-04 09:56:29'),
(35, 8, 'card2', NULL, NULL, 'Robotics & Automation', NULL, 'Enables precise force feedback for accurate motion control, assembly tasks, and safe human–robot interaction.', '2026-01-04 09:56:29', '2026-01-04 09:56:29'),
(36, 8, 'card2', NULL, NULL, 'Aerospace & Structural Testing', NULL, 'Captures multi-directional forces during component and structural testing to ensure reliability under extreme operating conditions.', '2026-01-04 09:56:29', '2026-01-04 09:56:29');

